// ChecksumEqualFold applies the EqualFold predicate on the "checksum" field.
func ChecksumEqualFold(v string) predicate.ScriptVersion {
	return predicate.ScriptVersion(sql.FieldEqualFold(FieldChecksum, v))
}

// ChecksumContainsFold applies the ContainsFold predicate on the "checksum" field.
func ChecksumContainsFold(v string) predicate.ScriptVersion {
	return predicate.ScriptVersion(sql.FieldContainsFold(FieldChecksum, v))
}

// HasScript applies the HasEdge predicate on the "script" edge.
func HasScript() predicate.ScriptVersion {
	return predicate.ScriptVersion(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ScriptTable, ScriptColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasScriptWith applies the HasEdge predicate on the "script" edge with a given conditions (other predicates).
func HasScriptWith(preds ...predicate.Script) predicate.ScriptVersion {
	return predicate.ScriptVersion(func(s *sql.Selector) {
		step := newScriptStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ScriptVersion) predicate.ScriptVersion {
	return predicate.ScriptVersion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ScriptVersion) predicate.ScriptVersion {
	return predicate.ScriptVersion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ScriptVersion) predicate.ScriptVersion {
	return predicate.ScriptVersion(sql.NotPredicates(p))
}
